package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed (their claims that count added up; a person's OPEN or PENDING claims dated within a hold of theirs, or any once their retirement date is reached, not bound by a statement, do not, nor do deferred claims) and
 * due-total (the figures of those claims, each with its late charge, added up; n/a when their grade has no rate today and no counting claim
 * has a figure, kept or at the grade in force on its date; at most the sheet's cap), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by before
 * today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a; the due-total and
 * overdue-total leave out the single highest and the single lowest figure when three or more people have one).
 *
 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
 * TOTALS when any of the sheet's three totals moved ({@link #record}).
 */
@Service
public class Rollup {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Every person's figures on the sheet now, in the order they were added. */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean figured = false;
            for (Claim c : all) {
                if (c.personId() != person.id() || !ClaimDue.countsLive(c, person, today)) {
                    continue;
                }
                claimed = claimed.add(c.amount());
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
                figured |= figure != null;
                if (figure != null) {
                    due = due.add(figure);
                    if (ClaimDue.isOpen(c) && c.dueBy().isBefore(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
                    : SettingRepository.capped(due, cap).toPlainString();
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
                    overdue.toPlainString()));
        }
        return new RollupBefore(figures);
    }

    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
    public void record(String sheetId, String by, RollupBefore before) {
        Map<Long, Figures> after = take(sheetId).figures();
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.figures().get(e.getKey());
            Figures now = e.getValue();
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        String claimedBefore = claimedTotal(before.figures());
        String dueBefore = dueTotal(before.figures());
        String claimedAfter = claimedTotal(after);
        String dueAfter = dueTotal(after);
        String overdueBefore = overdueTotal(before.figures());
        String overdueAfter = overdueTotal(after);
        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
                || !Objects.equals(overdueBefore, overdueAfter)) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
                    + dueAfter + " overdue-total=" + overdueAfter);
        }
    }

    private static String claimedTotal(Map<Long, Figures> figures) {
        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }

    private static String overdueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::overdueTotal).toList());
    }

    private static String dueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::dueTotal).toList());
    }

    /** The figures added up, skipping n/a, leaving out the single highest and the single lowest when three or more are left. */
    private static String trimmedTotal(List<String> values) {
        List<BigDecimal> figures = values.stream().filter((v) -> !v.equals("n/a")).map(BigDecimal::new).sorted().toList();
        if (figures.size() >= 3) {
            figures = figures.subList(1, figures.size() - 1);
        }
        return figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
 *  live; openedBy is who opened it, null when never opened; stated is whether it is bound to the figure statedDue
 *  (two decimals, null when it had none) by its person's last statement; corrects is the number of the claim a
 *  correction corrects (null for any other claim); roundsOn is the date that decides how its live figures round
 *  (the corrected claim's date for a correction, else its own; see Rounding); dueBy (yyyy-MM-dd) is its due-by, fixed
 *  when it was added; deferred is whether it is deferred on the sheet's today (see ClaimDue#deferred) and deferredUntil
 *  (yyyy-MM-dd) the date it was last deferred until (shown even once that date has passed), null when never deferred; proofs is its proofs count; splitFrom is the number of the claim it was split from (null for any other claim); log is its status log, oldest first: each status it has had, who made the change, the sheet's
 *  today (yyyy-MM-dd) then, and its due as shown at that moment (two decimals, or n/a); lockedBy is who has its editor
 *  open (null when no one does); lateEntry is whether it was added while its period was soft-closed; reminded (yyyy-MM-dd) is the last day a
 *  reminder was written for it, null when none. */
public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String dueBy, boolean deferred, String deferredUntil, int proofs, String splitFrom, List<LogLine> log,
        String lockedBy, boolean lateEntry, String reminded) {

    /** One line of a claim's status log as sent to the screen. */
    public record LogLine(String status, String by, String date, String due) {
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, ClaimLogRepository log, LocalDate today) {
        return from(claim, claims, log.of(claim.sheetId(), claim.id()), today);
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today) {
        return from(claim, claims, log, today, claims.lockedBy(claim.sheetId(), claim.id()),
                claims.lateEntry(claim.sheetId(), claim.id()), claims.remindedOn(claim.sheetId(), claim.id()));
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today, String lockedBy,
            boolean lateEntry, LocalDate reminded) {
        boolean deferred = ClaimDue.deferred(claim, today);
        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                Rounding.roundsOn(claim, claims).toString(), claim.dueBy().toString(),
                deferred, claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(), claim.splitFrom(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                lockedBy, lateEntry, reminded == null ? null : reminded.toString());
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Setting;
import net.officefloor.hq.app.setting.SettingRepository;

/**
 * A sheet's rates and settings as they stood at the end of a date: every one stored while the sheet's today was on or
 * before it counts (a later one stored for the same grade or key and from-date replacing an earlier), every one stored
 * later does not. The date stands in for the sheet's today.
 */
public final class SheetAsOf {

    private final LocalDate date;
    private final List<Rate> rates;
    private final List<Setting> settings;

    private SheetAsOf(LocalDate date, List<Rate> rates, List<Setting> settings) {
        this.date = date;
        this.rates = rates;
        this.settings = settings;
    }

    public static SheetAsOf read(String sheetId, LocalDate date, RateRepository rates, SettingRepository settings) {
        Map<String, Rate> byKey = new LinkedHashMap<>();
        for (Rate r : rates.storedBy(sheetId, date)) {
            byKey.put(r.grade() + "@" + r.from(), r);
        }
        Map<String, Setting> byFrom = new LinkedHashMap<>();
        for (Setting s : settings.storedBy(sheetId, date)) {
            byFrom.put(s.key() + "@" + s.from(), s);
        }
        return new SheetAsOf(date, new ArrayList<>(byKey.values()), new ArrayList<>(byFrom.values()));
    }

    public LocalDate date() {
        return date;
    }

    /** The rates as they stood, by grade, then from-date (one with none first), as RateRepository#list orders them. */
    public List<Rate> rates() {
        List<Rate> sorted = new ArrayList<>(rates);
        sorted.sort(java.util.Comparator.comparing(Rate::grade).thenComparing(Rate::from,
                java.util.Comparator.nullsFirst(java.util.Comparator.naturalOrder())));
        return sorted;
    }

    /** The settings as they stood, by key, then from-date (an undated one first), as SettingRepository#list orders them. */
    public List<Setting> settings() {
        List<Setting> sorted = new ArrayList<>(settings);
        sorted.sort(java.util.Comparator.comparing(Setting::key).thenComparing(Setting::from,
                java.util.Comparator.nullsFirst(java.util.Comparator.naturalOrder())));
        return sorted;
    }

    /** The grade's rate in force on a date (see RateRepository#find); null when none applies. */
    public Rate rate(String grade, LocalDate on) {
        Rate found = null;
        for (Rate r : rates) {
            if (!Objects.equals(r.grade(), grade) || (r.from() != null && r.from().isAfter(on))) {
                continue;
            }
            if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                found = r;
            }
        }
        return found == null || (found.to() != null && found.to().isBefore(on)) ? null : found;
    }

    /** The setting's value in force on a date (an undated one applies to every date); null when it has none. */
    public String value(String key, LocalDate on) {
        Setting found = null;
        for (Setting s : settings) {
            if (!s.key().equals(key) || (s.from() != null && s.from().isAfter(on))) {
                continue;
            }
            if (found == null || (s.from() != null && (found.from() == null || s.from().isAfter(found.from())))) {
                found = s;
            }
